export const CODA={enterAt:6,enterDuration:3,beamAt:10.2,beamDuration:1.15,tilt:-Math.PI/12,leaveAt:13.35,leaveDuration:3,fireworksAt:16.35};
export function codaPose(age){const beamAge=age-CODA.beamAt;return {visible:age>=CODA.enterAt&&age<CODA.leaveAt+CODA.leaveDuration,entrance:ease((age-CODA.enterAt)/CODA.enterDuration),leaving:age>=CODA.leaveAt,leave:ease((age-CODA.leaveAt)/CODA.leaveDuration),charge:ease((age-(CODA.beamAt-1.2))/1.2)*(1-ease((beamAge-CODA.beamDuration)/1.5)),beam:beamAge>=0&&beamAge<CODA.beamDuration,beamPower:beamAge<0?0:Math.sin(Math.PI*clamp(beamAge/CODA.beamDuration)),tilt:CODA.tilt*ease(beamAge/.55),smokeAge:Math.max(0,beamAge-.2)};}
export function createCoda(){return {fired:false};}
