function shape(c,points,fill){c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fillStyle=fill;c.fill();}
export function drawGodzilla(c,w,h,age,reduced=false){const p=codaPose(age);if(!p.visible)return null;const size=Math.max(.9,Math.min(1.45,Math.min(w,h)/650))*1.1,position=p.entrance*(1-p.leave),x=w+190+(w*.83-w-190)*position,dx=x-w*.5,R=w*1.5,ground=h*.79+R-Math.sqrt(Math.max(0,R*R-dx*dx))+22*size,walk=reduced?0:Math.sin((age-CODA.enterAt)*8)*(1-position)*3,facing=p.leaving?-1:1;c.save();c.translate(x,ground+walk);c.scale(size*facing,size);
 // Heavy tail, charcoal body, short arms and unmistakable jagged dorsal plates.
 c.beginPath();c.moveTo(19,-41);c.bezierCurveTo(65,-20,85,-8,123,-23);c.bezierCurveTo(90,13,46,9,14,-13);c.fillStyle='#263f3c';c.fill();
 for(let i=0;i<7;i++){const y=-113+i*13,x=18+i*2.6;shape(c,[[x-4,y+12],[x+16+(i%2)*5,y+1],[x+8,y-15],[x-7,y-3]],p.charge>0?'#69cfce':'#6a8c82');}
 c.beginPath();c.moveTo(-10,-121);c.bezierCurveTo(18,-132,30,-90,32,-59);c.bezierCurveTo(45,-27,21,-9,-12,-12);c.bezierCurveTo(-43,-17,-38,-61,-26,-82);c.lineTo(-33,-109);c.closePath();c.fillStyle='#344f47';c.fill();
 shape(c,[[-29,-105],[-47,-107],[-48,-124],[-23,-128],[-10,-116]],'#3f5c50');shape(c,[[-47,-110],[-26,-108],[-29,-103],[-47,-105]],'#132c2c');
 c.fillStyle='#ffce79';c.fillRect(-36,-120,5,3);shape(c,[[-39,-108],[-35,-104],[-31,-108]],'#dddac5');
 c.fillStyle='#516d55';c.beginPath();c.ellipse(-13,-54,16,34,-.12,0,7);c.fill();
 shape(c,[[-24,-87],[-45,-71],[-49,-62],[-39,-66],[-20,-69]],'#3e5b4d');shape(c,[[-46,-63],[-53,-62],[-48,-58],[-42,-62]],'#d3d7bf');
 for(const side of [-1,1]){const leg=side===-1?-19:15,offset=reduced?0:Math.sin((age-CODA.enterAt)*8+side*Math.PI*.5)*(1-position)*5;shape(c,[[leg-10,-29],[leg+10,-28],[leg+10+offset,-3],[leg-15+offset,-3],[leg-18+offset,-8]],side===-1?'#30483e':'#253f39');for(let i=0;i<3;i++)shape(c,[[leg-17+i*6+offset,-7],[leg-20+i*6+offset,-2],[leg-12+i*6+offset,-2]],'#b4bca2');}
 if(p.charge>0){c.globalAlpha=p.charge*.5;c.shadowBlur=reduced?0:12;c.shadowColor='#8eefff';c.fillStyle='#c0faff';c.beginPath();c.arc(-47,-107,4+p.charge*3,0,7);c.fill();}c.restore();return {x:x-47*size*facing,y:ground+walk-107*size,p};}
export function drawEnergyRay(c,mouth,target,age,reduced=false){if(!mouth?.p.beam)return;const p=mouth.p,power=p.beamPower;c.save();c.lineCap='round';c.globalAlpha=power*(reduced?.55:1);for(const [width,color] of [[25,'#55c7f62b'],[13,'#62d5ff88'],[5,'#efffff']]){c.strokeStyle=color;c.lineWidth=width;c.shadowColor='#55dcff';c.shadowBlur=reduced?0:18;c.beginPath();c.moveTo(mouth.x,mouth.y);c.lineTo(target.x,target.y);c.stroke();}c.shadowBlur=0;if(!reduced){c.strokeStyle='#a2f7ff';c.lineWidth=1.5;for(const side of [-1,1]){c.beginPath();c.moveTo(mouth.x,mouth.y);for(let i=1;i<=12;i++){const t=i/12;c.lineTo(mouth.x+(target.x-mouth.x)*t,mouth.y+(target.y-mouth.y)*t+Math.sin(i*2+age*10)*side*7*Math.sin(Math.PI*t));}c.stroke();}}c.fillStyle='#d7ffff';c.beginPath();c.arc(target.x,target.y,5+power*6,0,7);c.fill();c.restore();}
export function drawCapsuleSmoke(c,x,y,age,reduced=false){if(age<=0)return;c.save();for(let i=0;i<7;i++){const phase=reduced?i/7:((age*.32+i/7)%1),birth=phase/ .32;if(!reduced&&birth>age)continue;const dx=reduced?i%2*3:Math.sin(i*2.1+phase*3)*6;c.globalAlpha=(1-phase)*.25;c.fillStyle='#aeb7ba';c.beginPath();c.ellipse(x+dx+phase*13,y-phase*55,3+phase*10,4+phase*8,0,0,7);c.fill();}c.restore();}
export function drawFireworks(c,w,h,age,reduced=false){const t=age-CODA.fireworksAt;if(t<0)return;const colors=['#ffd36e','#7ef0ff','#ff7ab8','#9dff8a','#ffb36b','#c7a2ff'],rise=.4,life=1.6,radius=Math.min(w,h)*.15;c.save();c.globalCompositeOperation='lighter';c.lineCap='round';
 for(let b=0;b<8;b++){const bt=t-b*.45;if(bt<0||bt>rise+life)continue;const cx=w*.5+Math.sin(b*2.3)*w*.11,cy=h*.38+Math.cos(b*1.7)*h*.08,color=colors[b%colors.length];
  if(bt<rise){if(reduced)continue;const p=ease(bt/rise),y=mix(h*.79,cy,p);c.globalAlpha=.9;c.fillStyle='#fff3d6';c.beginPath();c.arc(cx,y,2.2,0,7);c.fill();c.strokeStyle=color;c.lineWidth=1.5;c.beginPath();c.moveTo(cx,y);c.lineTo(cx,Math.min(h*.79,y+28));c.stroke();continue;}
  const e=bt-rise,fade=1-clamp(e/life),spread=radius*(1-(1-clamp(e/.9))**3),drop=e*e*24;
  if(e<.15){c.globalAlpha=1-e/.15;c.fillStyle='#ffffff';c.beginPath();c.arc(cx,cy,10+e*80,0,7);c.fill();}
  c.globalAlpha=fade;c.fillStyle=color;c.strokeStyle=color;c.lineWidth=1.6;for(let i=0;i<28;i++){const a=i/28*Math.PI*2+b,r=spread*(.82+.18*Math.sin(i*7.1+b)),px=cx+Math.cos(a)*r,py=cy+Math.sin(a)*r+drop;if(!reduced){c.beginPath();c.moveTo(cx+Math.cos(a)*r*.72,cy+Math.sin(a)*r*.72+drop*.7);c.lineTo(px,py);c.stroke();}c.beginPath();c.arc(px,py,.8+2*fade,0,7);c.fill();}}
 c.restore();}
